package com.synexia.rewrite;

import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;
import org.junit.jupiter.api.Test;
import org.openrewrite.InMemoryExecutionContext;
import org.openrewrite.SourceFile;
import org.openrewrite.config.Environment;
import org.openrewrite.internal.InMemoryLargeSourceSet;
import org.openrewrite.text.PlainText;

import static org.junit.jupiter.api.Assertions.*;

/** Actual OpenRewrite engine: generated bytes, fixed point, drift/duplicate refusal. */
final class M3EclipseMultimapRecipeTest {
    private static M3GpuToolJoinManifest sealed() {
        return M3GpuToolJoinManifest.load(
                "/com/synexia/rewrite/sdk-eclipse-multimap-20261017/",
                M3EclipseMultimapRecipeTest.class::getResourceAsStream, () -> {});
    }

    private static List<SourceFile> postimages() {
        List<SourceFile> candidates = new ArrayList<>();
        for (var target : sealed().targets()) {
            candidates.add(PlainText.builder().sourcePath(Path.of(target.path()))
                    .text(target.text()).build());
        }
        return candidates;
    }

    private static List<org.openrewrite.Result> run(List<SourceFile> inputs, List<Throwable> errors) {
        return new M3EclipseMultimapRecipe().run(new InMemoryLargeSourceSet(inputs),
                new InMemoryExecutionContext(errors::add)).getChangeset().getAllResults();
    }

    @Test void generatesEveryExactJavaPostimage() {
        List<Throwable> errors = new ArrayList<>();
        var emitted = run(List.of(), errors);
        assertTrue(errors.isEmpty(), errors.toString());
        assertEquals(5, emitted.size());
        for (var target : sealed().targets()) {
            var match = emitted.stream().filter(r -> r.getAfter() != null
                    && r.getAfter().getSourcePath().toString().replace('\\', '/')
                    .equals(target.path())).findFirst().orElseThrow();
            assertEquals(target.after(),
                    M3GpuToolJoinManifest.sha256(match.getAfter().printAll()));
            assertEquals(target.text(), match.getAfter().printAll());
        }
    }

    @Test void secondRunIsAContentIdenticalFixedPoint() {
        List<Throwable> errors = new ArrayList<>();
        var emitted = run(postimages(), errors);
        assertTrue(errors.isEmpty(), errors.toString());
        assertEquals(0, emitted.size());
    }

    @Test void occupiedForeignSourceRefusesEntireBatch() {
        var entries = postimages();
        var first = entries.get(0);
        entries.set(0, PlainText.builder().sourcePath(first.getSourcePath())
                .text(first.printAll() + "drift").build());
        List<Throwable> errors = new ArrayList<>();
        try { run(entries, errors); } catch (RuntimeException expected) { errors.add(expected); }
        assertFalse(errors.isEmpty(), "source drift must refuse generation");
    }

    @Test void duplicateInputOwnersRefuse() {
        var entries = postimages();
        entries.add(entries.get(0));
        List<Throwable> errors = new ArrayList<>();
        try { run(entries, errors); } catch (RuntimeException expected) { errors.add(expected); }
        assertFalse(errors.isEmpty(), "duplicate source owner must refuse");
    }

    @Test void namedRecipeCanBeActivatedFromClasspath() {
        var recipe = Environment.builder().scanClassLoader(getClass().getClassLoader()).build()
                .activateRecipes("com.synexia.m3.EclipseMultimaps20261017");
        assertTrue(recipe.validateAll().stream().allMatch(v -> v.isValid()));
    }
}
